import React, { useState } from "react";
import { sendMessage } from "../services/api";

const ChatPage = () => {
  const [message, setMessage] = useState("");
  const [chat, setChat] = useState([]);

  const handleSend = async () => {
    if (!message) return;

    const res = await sendMessage(message);

    setChat([...chat, { user: message, bot: res.data.reply }]);
    setMessage("");
  };

  return (
    <div style={styles.container}>

      {/* HEADER */}
      <div style={styles.header}>
        EduSaarthi Chatbot 🤖
      </div>

      {/* CHAT BOX */}
      <div style={styles.chatBox}>
        {chat.map((c, i) => (
          <div key={i}>
            <div style={styles.userMsg}>
              <span style={styles.userBubble}>{c.user}</span>
            </div>

            <div style={styles.botMsg}>
              <span style={styles.botBubble}>{c.bot}</span>
            </div>
          </div>
        ))}
      </div>

      {/* INPUT */}
      <div style={styles.inputArea}>
        <input
          style={styles.input}
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Ask something..."
        />

        <button style={styles.button} onClick={handleSend}>
          Send
        </button>
      </div>

    </div>
  );
};

export default ChatPage;

const styles = {
  container: {
    height: "100vh",
    display: "flex",
    flexDirection: "column",
    background: "#0f172a",
    color: "white",
  },
  header: {
    padding: "15px",
    background: "#111827",
    color: "#38bdf8",
    textAlign: "center",
    fontSize: "18px",
  },
  chatBox: {
    flex: 1,
    padding: "20px",
    overflowY: "auto",
  },
  userMsg: {
    textAlign: "right",
    margin: "10px 0",
  },
  botMsg: {
    textAlign: "left",
    margin: "10px 0",
  },
  userBubble: {
    background: "#38bdf8",
    color: "black",
    padding: "10px 15px",
    borderRadius: "15px",
  },
  botBubble: {
    background: "#1e293b",
    padding: "10px 15px",
    borderRadius: "15px",
  },
  inputArea: {
    display: "flex",
    padding: "10px",
    background: "#111827",
  },
  input: {
    flex: 1,
    padding: "10px",
    borderRadius: "6px",
    border: "none",
    background: "#334155",
    color: "white",
  },
  button: {
    marginLeft: "10px",
    padding: "10px 15px",
    border: "none",
    background: "#38bdf8",
    color: "black",
    borderRadius: "6px",
    cursor: "pointer",
  },
};
